<div class="page-heading"><div><p class="eyebrow">USER ADMINISTRATION</p><h1><?= e($title) ?></h1></div></div>
<section class="card floating-card" data-card-key="user-form"><h2 class="floating-label">Account &amp; permissions</h2><div class="card-body"><form action="<?= $record?'/users/' . e($record['id']):'/users/add' ?>" method="post" data-ajax-form><?= csrf() ?>
<div class="form-grid"><?php foreach (['username'=>'Username','name'=>'Display name','email'=>'Email'] as $field=>$label): ?><label class="form-label"><?= e($label) ?><input class="form-control mb-3" name="<?= e($field) ?>" type="<?= $field==='email'?'email':'text' ?>" value="<?= e($record[$field] ?? '') ?>" maxlength="<?= $field==='email'?254:($field==='name'?160:80) ?>" required></label><?php endforeach; ?></div>
<label class="form-label">Role<select class="form-select mb-3" name="role"><?php foreach (App\Middleware\Permissions::ROLES as $role=>$permissions): ?><option <?= ($record['role'] ?? 'Read Only')===$role?'selected':'' ?>><?= e($role) ?></option><?php endforeach; ?></select></label>
<?php if (!$record): ?><label class="form-label">Initial password<input class="form-control mb-3" name="password" type="password" minlength="12" maxlength="1024" autocomplete="new-password" required></label><p class="text-secondary">A random avatar seed is created automatically. No default passwords or photos are installed.</p><?php endif; ?>
<label class="form-check mb-3"><input type="checkbox" name="active" class="form-check-input" <?= ($record['active'] ?? true)?'checked':'' ?>><span class="form-check-label">Account active</span></label><div class="form-error" role="alert" hidden></div><button class="btn btn-primary">Save user</button></form></div></section>
<section class="card floating-card" data-card-key="role-permissions"><h2 class="floating-label">Role permission map</h2><div class="card-body"><?php foreach (App\Middleware\Permissions::ROLES as $role=>$permissions): ?><div class="record-row"><div><strong><?= e($role) ?></strong><small><?= e(implode(', ',$permissions)) ?></small></div></div><?php endforeach; ?></div></section>
